import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

void main() {
  test(
    'Home bootstrap delegates catalog snapshots and keeps history single-flight',
    () {
      final state = File('lib/screens/home_screen.dart').readAsStringSync();
      final data = File('lib/screens/home_screen_data.dart').readAsStringSync();
      final adapter = File(
        'lib/services/media/anime_home_snapshot_adapter.dart',
      ).readAsStringSync();

      // Catalog cache/fresh coordination now belongs to the shared lifecycle.
      expect(state, contains('HomeSnapshotController<HomeData>'));
      expect(state, contains('AnimeHomeSnapshotAdapter'));
      expect(state, isNot(contains('_cachedSnapshotLoadInFlight')));
      expect(data, isNot(contains('Future<void> _loadCachedHomeData()')));

      // The Anime adapter preserves the persisted-cache behavior that existed
      // before the lifecycle migration, including accepting expired snapshots
      // during bootstrap while a fresh catalog load runs.
      expect(adapter, contains('Future<HomeData?> loadCached()'));
      expect(adapter, contains('allowExpired: true'));
      expect(adapter, contains('Future<HomeData> loadFresh'));

      // Continue Watching is secondary local state and retains its dedicated
      // single-flight + trailing forced refresh semantics (PERF-N05).
      expect(state, contains('_continueWatchingLoadInFlight'));
      expect(
        data,
        contains('_loadContinueWatching({bool forceRefresh = false})'),
      );
      expect(data, contains('final future = _drainContinueWatchingLoads();'));
      expect(data, contains('while (_continueWatchingRerunRequested);'));
      expect(data, contains('_readContinueWatching()'));

      // Failure logging for the remaining secondary storage read is preserved.
      expect(data, contains('[Home] Continue watching load failed:'));
    },
  );
}

import 'package:flutter_test/flutter_test.dart';
import 'package:goanime/services/manga/manga_provider_policy.dart';
import 'package:goanime/services/manga/manga_request_scheduler.dart';
import 'package:goanime/services/manga/manga_search_coordinator.dart';
import 'package:goanime/services/manga/manga_source_registry.dart';
import 'package:goanime_core/goanime_core.dart';

import '../../helpers/fake_manga_source_provider.dart';

void main() {
  test('Manga search cache is bounded and renews LRU recency on hit', () async {
    var searchCount = 0;
    final provider = FakeMangaSourceProvider(
      sourceId: 'ptbr.cache',
      searchHandler: (request) async {
        searchCount++;
        final id = request.query.toLowerCase();
        return MangaSearchPage(
          items: [
            MangaSourceOccurrence(
              sourceId: 'ptbr.cache',
              mangaId: id,
              title: request.query,
            ),
          ],
        );
      },
    );
    const providerPolicy = MangaProviderPolicy(
      sourceId: 'ptbr.cache',
      maxConcurrent: 2,
      minimumRequestSpacing: Duration.zero,
    );
    final registry = MangaSourceRegistry(
      providers: [provider],
      policies: const {'ptbr.cache': providerPolicy},
    );
    final scheduler = MangaRequestScheduler(
      policies: const {'ptbr.cache': providerPolicy},
    );
    final coordinator = MangaSearchCoordinator(
      registry: registry,
      scheduler: scheduler,
      cachePolicy: const CachePolicy(ttl: Duration(minutes: 5), maxEntries: 2),
    );

    await coordinator.search('one', ownerToken: Object()).toList();
    await coordinator.search('two', ownerToken: Object()).toList();
    await coordinator.search('one', ownerToken: Object()).toList();
    expect(searchCount, 2, reason: 'one should be a cache hit and become MRU');

    await coordinator.search('three', ownerToken: Object()).toList();
    expect(searchCount, 3);

    await coordinator.search('two', ownerToken: Object()).toList();
    expect(
      searchCount,
      4,
      reason: 'two should have been evicted after one renewed its recency',
    );

    scheduler.dispose();
  });
}

import 'dart:async';

import 'package:flutter_test/flutter_test.dart';
import 'package:goanime/services/manga/manga_availability_models.dart';
import 'package:goanime/services/manga/manga_provider_policy.dart';
import 'package:goanime/services/manga/manga_request_scheduler.dart';
import 'package:goanime/services/manga/manga_search_coordinator.dart';
import 'package:goanime/services/manga/manga_source_registry.dart';
import 'package:goanime_core/goanime_core.dart';

import '../../helpers/fake_manga_source_provider.dart';

void main() {
  test(
    'emits readable results progressively and collapses trusted A B match',
    () async {
      final aSearch = Completer<MangaSearchPage>();
      final bSearch = Completer<MangaSearchPage>();
      final cSearch = Completer<MangaSearchPage>();
      final providers = [
        _provider('ptbr.a', aSearch),
        _provider('ptbr.b', bSearch),
        _provider('ptbr.c', cSearch),
      ];
      final policies = {
        for (final provider in providers)
          provider.sourceId: MangaProviderPolicy(
            sourceId: provider.sourceId,
            maxConcurrent: 1,
            minimumRequestSpacing: Duration.zero,
          ),
      };
      final registry = MangaSourceRegistry(
        providers: providers,
        policies: policies,
      );
      final scheduler = MangaRequestScheduler(policies: policies);
      var nextWorkId = 0;
      final coordinator = MangaSearchCoordinator(
        registry: registry,
        scheduler: scheduler,
        newWorkId: () => 'mw_${++nextWorkId}',
      );
      final events = <MangaSearchUpdate>[];
      final done = Completer<void>();
      coordinator
          .search('Example', ownerToken: Object())
          .listen(events.add, onDone: done.complete);

      aSearch.complete(_page('ptbr.a', 'a-1'));
      await _flush();

      expect(events, hasLength(1));
      expect(events.single.isComplete, isFalse);
      expect(events.single.results, hasLength(1));
      expect(events.single.results.single.sourceLinks, hasLength(1));
      expect(
        events.single.results.single.sourceLinks.single.occurrence.sourceId,
        'ptbr.a',
      );

      bSearch.complete(_page('ptbr.b', 'b-1'));
      cSearch.completeError(StateError('provider unavailable'));
      await done.future;

      expect(events.last.isComplete, isTrue);
      expect(events.last.results, hasLength(1));
      expect(events.last.results.single.work.workId, 'mw_1');
      expect(
        events.last.results.single.sourceLinks
            .map((link) => link.occurrence.sourceId)
            .toSet(),
        {'ptbr.a', 'ptbr.b'},
      );
      expect(events.last.results.single.evidence, hasLength(2));
    },
  );

  test(
    'an older generation cannot emit or persist after a newer search starts',
    () async {
      final oldSearch = Completer<MangaSearchPage>();
      final persistence = _RecordingSearchPersistence();
      final provider = FakeMangaSourceProvider(
        sourceId: 'ptbr.a',
        searchHandler: (request) {
          if (request.query == 'old') return oldSearch.future;
          return Future.value(_page('ptbr.a', 'new-1', title: 'New Work'));
        },
        detailsHandler: (occurrence) async => MangaSourceDetails(
          occurrence: occurrence,
          externalIds: [
            MangaExternalId(namespace: 'mangadex', value: occurrence.mangaId),
          ],
        ),
      );
      const policy = MangaProviderPolicy(
        sourceId: 'ptbr.a',
        maxConcurrent: 2,
        minimumRequestSpacing: Duration.zero,
      );
      final registry = MangaSourceRegistry(
        providers: [provider],
        policies: const {'ptbr.a': policy},
      );
      final scheduler = MangaRequestScheduler(
        policies: const {'ptbr.a': policy},
      );
      var nextWorkId = 0;
      final coordinator = MangaSearchCoordinator(
        registry: registry,
        scheduler: scheduler,
        persistence: persistence,
        newWorkId: () => 'mw_${++nextWorkId}',
      );
      final oldEvents = <MangaSearchUpdate>[];
      final oldDone = Completer<void>();
      coordinator
          .search('old', ownerToken: Object())
          .listen(oldEvents.add, onDone: oldDone.complete);

      final newEvents = await coordinator
          .search('new', ownerToken: Object())
          .toList();
      expect(newEvents.last.isComplete, isTrue);
      expect(newEvents.last.results.single.work.canonicalTitle, 'New Work');
      expect(
        persistence.records
            .map((record) => record.work.canonicalTitle)
            .toList(),
        ['New Work'],
      );

      oldSearch.complete(_page('ptbr.a', 'old-1', title: 'Old Work'));
      await oldDone.future;
      expect(oldEvents, isEmpty);
      expect(
        persistence.records
            .map((record) => record.work.canonicalTitle)
            .toList(),
        ['New Work'],
      );
    },
  );

  test(
    'serves cached results immediately for identical query within TTL',
    () async {
      var searchCount = 0;
      final provider = FakeMangaSourceProvider(
        sourceId: 'ptbr.a',
        searchHandler: (request) {
          searchCount++;
          return Future.value(
            _page('ptbr.a', 'cached-1', title: 'Cached Work'),
          );
        },
        detailsHandler: (occurrence) async =>
            MangaSourceDetails(occurrence: occurrence),
      );
      const policy = MangaProviderPolicy(
        sourceId: 'ptbr.a',
        maxConcurrent: 2,
        minimumRequestSpacing: Duration.zero,
      );
      final registry = MangaSourceRegistry(
        providers: [provider],
        policies: const {'ptbr.a': policy},
      );
      final scheduler = MangaRequestScheduler(
        policies: const {'ptbr.a': policy},
      );
      final coordinator = MangaSearchCoordinator(
        registry: registry,
        scheduler: scheduler,
        cacheTtl: const Duration(minutes: 5),
      );

      final firstResults = await coordinator
          .search('Cached Query', ownerToken: Object())
          .toList();
      expect(
        firstResults.last.results.single.work.canonicalTitle,
        'Cached Work',
      );
      expect(searchCount, 1);

      final cachedResults = await coordinator
          .search('cached query', ownerToken: Object())
          .toList();
      expect(
        cachedResults.last.results.single.work.canonicalTitle,
        'Cached Work',
      );
      expect(cachedResults.last.isComplete, isTrue);
      expect(searchCount, 1); // Provider not called again due to cache hit
    },
  );

  test(
    'evicts least-recent search when CachePolicy capacity is exceeded',
    () async {
      var searchCount = 0;
      final provider = FakeMangaSourceProvider(
        sourceId: 'ptbr.a',
        searchHandler: (request) {
          searchCount++;
          return Future.value(
            _page(
              'ptbr.a',
              '${request.query}-$searchCount',
              title: request.query,
            ),
          );
        },
        detailsHandler: (occurrence) async =>
            MangaSourceDetails(occurrence: occurrence),
      );
      const providerPolicy = MangaProviderPolicy(
        sourceId: 'ptbr.a',
        maxConcurrent: 2,
        minimumRequestSpacing: Duration.zero,
      );
      final registry = MangaSourceRegistry(
        providers: [provider],
        policies: const {'ptbr.a': providerPolicy},
      );
      final scheduler = MangaRequestScheduler(
        policies: const {'ptbr.a': providerPolicy},
      );
      final coordinator = MangaSearchCoordinator(
        registry: registry,
        scheduler: scheduler,
        cachePolicy: const CachePolicy(
          ttl: Duration(minutes: 5),
          maxEntries: 1,
          staleWhileRevalidate: false,
        ),
      );

      await coordinator.search('first', ownerToken: Object()).toList();
      await coordinator.search('second', ownerToken: Object()).toList();
      expect(searchCount, 2);

      await coordinator.search('first', ownerToken: Object()).toList();
      expect(
        searchCount,
        3,
        reason: 'the first query must have been evicted when capacity is one',
      );
    },
  );
}

final class _RecordingSearchPersistence implements MangaSearchPersistence {
  final List<MangaAvailabilityRecord> records = [];

  @override
  Future<void> persist(MangaAvailabilityRecord record) async {
    records.add(record);
  }
}

FakeMangaSourceProvider _provider(
  String sourceId,
  Completer<MangaSearchPage> search,
) {
  return FakeMangaSourceProvider(
    sourceId: sourceId,
    searchHandler: (_) => search.future,
    detailsHandler: (occurrence) async => MangaSourceDetails(
      occurrence: occurrence,
      authors: const ['Shared Author'],
      externalIds: const [
        MangaExternalId(namespace: 'mangadex', value: 'trusted-work'),
      ],
    ),
  );
}

MangaSearchPage _page(
  String sourceId,
  String mangaId, {
  String title = 'Example Work',
}) {
  return MangaSearchPage(
    items: [
      MangaSourceOccurrence(sourceId: sourceId, mangaId: mangaId, title: title),
    ],
  );
}

Future<void> _flush() async {
  await Future<void>.delayed(Duration.zero);
  await Future<void>.delayed(Duration.zero);
}

import 'package:flutter_test/flutter_test.dart';
import 'package:goanime/services/download/download_models.dart';
import 'package:goanime/services/media/anime_download_job_adapter.dart';
import 'package:goanime_core/goanime_core.dart';

void main() {
  test(
    'maps Anime download lifecycle and progress without changing semantics',
    () {
      final item = DownloadItem(
        id: 'download-1',
        animeId: 'anime-1',
        animeName: 'Anime',
        episodeNumber: '3',
        episodeTitle: 'Episode 3',
        videoUrl: 'https://example.test/video',
        thumbnailUrl: 'https://example.test/thumb',
        status: DownloadStatus.downloading,
        progress: 0.5,
        bytesDownloaded: 512,
        totalBytes: 1024,
      );

      final job = const AnimeDownloadJobAdapter().fromItem(item);

      expect(job.mediaKind, MediaKind.anime);
      expect(job.jobId, 'download-1');
      expect(job.entityId, 'anime-1');
      expect(job.phase, MediaDownloadJobPhase.transferring);
      expect(job.progress.bytesReceived, 512);
      expect(job.progress.expectedBytes, 1024);
      expect(job.progress.fraction, 0.5);
      expect(job.payload.item, same(item));
    },
  );

  test(
    'does not invent an expected byte count when Anime total is unknown',
    () {
      final item = DownloadItem(
        id: 'download-2',
        animeId: 'anime-2',
        animeName: 'Anime',
        episodeNumber: '1',
        episodeTitle: 'Episode 1',
        videoUrl: 'https://example.test/video',
        thumbnailUrl: '',
        status: DownloadStatus.queued,
        progress: 0,
        bytesDownloaded: 32,
        totalBytes: 0,
      );

      final job = const AnimeDownloadJobAdapter().fromItem(item);

      expect(job.progress.bytesReceived, 32);
      expect(job.progress.expectedBytes, isNull);
      expect(job.progress.fraction, 0);
    },
  );

  test('maps every Anime state to its shared lifecycle phase', () {
    const expected = <DownloadStatus, MediaDownloadJobPhase>{
      DownloadStatus.queued: MediaDownloadJobPhase.queued,
      DownloadStatus.downloading: MediaDownloadJobPhase.transferring,
      DownloadStatus.paused: MediaDownloadJobPhase.paused,
      DownloadStatus.completed: MediaDownloadJobPhase.completed,
      DownloadStatus.failed: MediaDownloadJobPhase.failed,
      DownloadStatus.cancelled: MediaDownloadJobPhase.cancelled,
    };

    for (final entry in expected.entries) {
      expect(AnimeDownloadJobAdapter.phaseFor(entry.key), entry.value);
    }
  });
}

