import 'dart:async';

import 'package:flutter_test/flutter_test.dart';
import 'package:goanime/models/jikan_models.dart';
import 'package:goanime/services/jikan_service.dart';
import 'package:goanime/services/media/anime_home_snapshot_adapter.dart';

void main() {
  test('AnimeHomeSnapshotAdapter reads expired persisted snapshots', () async {
    final cached = _homeData(1, 'Cached');
    final service = _FakeHomeJikanService(cached: cached);
    final adapter = AnimeHomeSnapshotAdapter(jikanService: service);

    expect(await adapter.loadCached(), same(cached));
    expect(service.allowExpiredValues, [true]);
  });

  test('AnimeHomeSnapshotAdapter forwards fresh refresh intent', () async {
    final fresh = _homeData(2, 'Fresh');
    final service = _FakeHomeJikanService(fresh: fresh);
    final adapter = AnimeHomeSnapshotAdapter(jikanService: service);

    expect(await adapter.loadFresh(forceRefresh: false), same(fresh));
    expect(await adapter.loadFresh(forceRefresh: true), same(fresh));
    expect(service.forceRefreshValues, [false, true]);
  });

  test('AnimeHomeSnapshotAdapter bounds a stalled fresh load', () async {
    final service = _FakeHomeJikanService(
      freshFuture: Completer<HomeData>().future,
    );
    final adapter = AnimeHomeSnapshotAdapter(
      jikanService: service,
      freshTimeout: const Duration(milliseconds: 10),
    );

    await expectLater(
      adapter.loadFresh(forceRefresh: false),
      throwsA(isA<TimeoutException>()),
    );
  });
}

final class _FakeHomeJikanService extends JikanService {
  _FakeHomeJikanService({this.cached, this.fresh, this.freshFuture})
    : super(propagateErrors: true);

  final HomeData? cached;
  final HomeData? fresh;
  final Future<HomeData>? freshFuture;
  final List<bool> allowExpiredValues = [];
  final List<bool> forceRefreshValues = [];

  @override
  Future<HomeData?> loadCachedHomeDataSnapshot({bool allowExpired = false}) {
    allowExpiredValues.add(allowExpired);
    return Future.value(cached);
  }

  @override
  Future<HomeData> loadHomeData({bool forceRefresh = false}) {
    forceRefreshValues.add(forceRefresh);
    final pending = freshFuture;
    if (pending != null) return pending;
    return Future.value(fresh ?? _homeData(3, 'Default'));
  }
}

HomeData _homeData(int id, String title) {
  final anime = JikanAnime(malId: id, title: title, imageUrl: '');
  return HomeData(
    seasonAnimes: [anime],
    todaysReleases: const [],
    topAnimes: const [],
    actionAnimes: const [],
    romanceAnimes: const [],
    comedyAnimes: const [],
    fantasyAnimes: const [],
  );
}

import 'package:flutter_test/flutter_test.dart';
import 'package:goanime/models/history_anime.dart';
import 'package:goanime/services/media/anime_progress_event_adapter.dart';
import 'package:goanime_core/goanime_core.dart';

void main() {
  test('maps anime playback progress without changing time units', () {
    final history = HistoryAnime(
      animeId: 'anime-1',
      title: 'Anime',
      coverImage: '',
      watchedAt: '2026-08-24T10:00:00Z',
      updatedAt: '2026-08-24T11:00:00Z',
      lastEpisode: 'Episódio 7',
      episodeNumber: 7,
      progress: 0.5,
      positionSeconds: 321,
      durationSeconds: 642,
      isDubMode: true,
    );

    final event = const AnimeProgressEventAdapter().fromHistory(history);

    expect(event, isNotNull);
    expect(event!.mediaKind, MediaKind.anime);
    expect(event.entityId, 'anime-1');
    expect(event.unitId, 'episode:7');
    expect(event.updatedAt, DateTime.utc(2026, 8, 24, 11));
    expect(event.completed, isFalse);
    expect(event.payload.episodeNumber, 7);
    expect(event.payload.positionSeconds, 321);
    expect(event.payload.durationSeconds, 642);
    expect(event.payload.progress, 0.5);
    expect(event.payload.isDubMode, isTrue);
  });

  test(
    'uses anime completion semantics and rejects legacy rows without unit identity',
    () {
      final completed = HistoryAnime(
        animeId: 'anime-1',
        title: 'Anime',
        coverImage: '',
        watchedAt: '2026-08-24T10:00:00Z',
        lastEpisode: 'Episódio 3',
        episodeNumber: 3,
        progress: 0.85,
      );
      final legacy = HistoryAnime(
        animeId: 'anime-1',
        title: 'Anime',
        coverImage: '',
        watchedAt: '2026-08-24T10:00:00Z',
        lastEpisode: 'Episódio desconhecido',
      );

      final adapter = const AnimeProgressEventAdapter();

      expect(adapter.fromHistory(completed)!.completed, isTrue);
      expect(adapter.fromHistory(legacy), isNull);
    },
  );
}

import 'package:flutter_test/flutter_test.dart';
import 'package:goanime/models/history_anime.dart';
import 'package:goanime/models/user_anime_state.dart';
import 'package:goanime/models/watchlist_anime.dart';
import 'package:goanime/services/media/anime_user_state_event_adapter.dart';
import 'package:goanime_core/goanime_core.dart';

void main() {
  const adapter = AnimeUserStateEventAdapter();

  test('full anime state emits all three independent domain events', () {
    final state = UserAnimeState(
      animeId: '42',
      title: 'Anime',
      coverImage: 'cover.jpg',
      saved: true,
      status: UserAnimeStatus.watching,
      score: 8,
      episodeNumber: 3,
      progress: 0.5,
      updatedAt: DateTime.utc(2026, 8, 24, 12),
      playbackUpdatedAt: DateTime.utc(2026, 8, 24, 10),
      watchlistUpdatedAt: DateTime.utc(2026, 8, 24, 11),
      ratingUpdatedAt: DateTime.utc(2026, 8, 24, 12),
    );

    final events = adapter.fromState(state);

    expect(events.map((event) => event.category), <UserMediaStateCategory>[
      UserMediaStateCategory.rating,
      UserMediaStateCategory.library,
      UserMediaStateCategory.progress,
    ]);
    expect(events.every((event) => event.mediaKind == MediaKind.anime), isTrue);
    expect(events.every((event) => !event.partial), isTrue);
    expect(events.every((event) => !event.tombstone), isTrue);
    expect(events.every((event) => identical(event.payload, state)), isTrue);
  });

  test(
    'playback tombstone maps only to progress with its domain timestamp',
    () {
      final deletedAt = DateTime.utc(2026, 8, 24, 10);
      final state = UserAnimeState.playbackTombstone(
        '42',
        deletedAt: deletedAt,
      );

      final events = adapter.fromState(state);

      expect(events, hasLength(1));
      expect(events.single.category, UserMediaStateCategory.progress);
      expect(events.single.updatedAt, deletedAt);
      expect(events.single.tombstone, isTrue);
      expect(events.single.partial, isTrue);
    },
  );

  test('watchlist removal maps to a library tombstone', () {
    final removedAt = DateTime.utc(2026, 8, 24, 11);
    final state = UserAnimeState.watchlistRemoval('42', removedAt: removedAt);

    final events = adapter.fromState(state);

    expect(events, hasLength(1));
    expect(events.single.category, UserMediaStateCategory.library);
    expect(events.single.updatedAt, removedAt);
    expect(events.single.tombstone, isTrue);
    expect(events.single.partial, isTrue);
  });

  test('composite sparse state emits each partial domain independently', () {
    final state = UserAnimeState.fromJson(<String, dynamic>{
      'animeId': '42',
      'title': 'Anime',
      'coverImage': 'cover.jpg',
      'saved': true,
      'score': 9,
      'updatedAt': '2026-08-24T12:00:00.000Z',
      'watchlistUpdatedAt': '2026-08-24T11:00:00.000Z',
      'ratingUpdatedAt': '2026-08-24T12:00:00.000Z',
    });

    final events = adapter.fromState(state);

    expect(events.map((event) => event.category), <UserMediaStateCategory>[
      UserMediaStateCategory.rating,
      UserMediaStateCategory.library,
    ]);
    expect(events.every((event) => event.partial), isTrue);
    expect(events.every((event) => !event.tombstone), isTrue);
  });

  test('global anime tombstone fans out to every shared state category', () {
    final state = UserAnimeState.tombstone('42');

    final events = adapter.fromState(state);

    expect(events, hasLength(3));
    expect(
      events.map((event) => event.category).toSet(),
      UserMediaStateCategory.values.toSet(),
    );
    expect(events.every((event) => event.tombstone), isTrue);
    expect(events.every((event) => !event.partial), isTrue);
  });

  test('normal partial updates are not misclassified as tombstones', () {
    final playback = UserAnimeState.playbackUpdate(
      HistoryAnime(
        animeId: '42',
        title: 'Anime',
